/*
Grammar used:
Expr  := OrExpr
OrExpr := AddExpr { "or" AddExpr }*
AddExpr := MulExpr { '+' MulExpr }*
MulExpr := Atom { '*' Atom }*
Atom := number | '(' Expr ')'

We may insert "or" anywhere as long as resulting expression remains valid.
Since "or" has the lowest precedence, the optimal strategy is:
- split the expression into several valid AddExpr pieces joined by or,
- maximize bitwise OR of values of these pieces.

DP over token boundaries:
best[l][r] = maximum value obtainable from substring s[l..r] that is a valid expression,
with inserted "or" allowed.
Need parser info for substrings that are valid AddExpr / MulExpr / Atom in original string.

Because full general CFG DP would be heavy, we exploit the grammar structure and parse
the original expression into syntax tree, then DP on every node:
For any node, answer = max over:
- keep node as-is
- if node is Add/Mul/Or, split between children with inserted or where grammar allows.

Observation:
Any place between consecutive terms of an AddExpr or MulExpr or OrExpr can be turned into
an "or" only if both sides are valid AddExprs.
Inside a product, a factor alone is an Atom, hence also MulExpr/AddExpr, and a suffix/prefix
product of atoms is also MulExpr and therefore AddExpr. So any split between factors is allowed.
Similarly between addends.
Thus for a sequence combined by + or * or or, we can partition the sequence into groups;
each group's value is evaluated with the original operator inside the group, and final answer
is OR of group values. Recursively each group can itself be enhanced internally.

So for each node we compute:
val_keep = original value
best = maximum OR by partitioning its immediate sequence children into contiguous groups,
where each group contributes best_group_value = value of combined children in that group
with original operator, but children themselves may already be enhanced internally only if
that does not change syntax. Since inserting or inside a child is always allowed within that child,
group value should be "best as a valid AddExpr without introducing top-level or outside group".
For operator nodes +/*, a group is same operator over consecutive child expressions, each child
can be fully optimized internally. For OR node, group over consecutive children with or is just OR
of their best values, so whole node best is OR of all children bests.

Need two values per node:
- plain: value if no top-level inserted-or splits this node's root operator; children may still be optimized internally.
  For number/plain atom => number.
  For + node => sum(plain child)
  For * node => product(plain child)
  For or node => bitwise_or(best child) because existing or already separates.
- best: maximum obtainable from this subtree as an AddExpr after arbitrary insertions.

For +/* sequence node, best = max OR over partition into groups, each group value is combine(plain children in group).
Since OR is monotone, using child plain (already internally optimized) is correct.
DP over sequence:
dp[i] = max OR for suffix from i.
Transition group i..j => groupVal op-combine plains, candidate = groupVal | dp[j+1].

For or node, best = OR of best children.
*/

typedef enum { NODE_NUM, NODE_ADD, NODE_MUL, NODE_OR } Type;

typedef struct Node {
    Type type;
    ll num;
    struct Node **ch;
    int cnt, cap;
    ll plain;
    ll best;
} Node;

static Node* new_node(Type t) {
    Node *x = (Node*)calloc(1, sizeof(Node));
    x->type = t;
    return x;
}
static Node* new_num(ll v) {
    Node *x = new_node(NODE_NUM);
    x->num = v;
    return x;
}
static void add_child(Node *p, Node *c) {
    if (p->cnt == p->cap) {
        p->cap = p->cap ? p->cap * 2 : 4;
        p->ch = (Node**)realloc(p->ch, p->cap * sizeof(Node*));
    }
    p->ch[p->cnt++] = c;
}

static void skip_spaces() {
    while (pos < n && isspace((unsigned char)s[pos])) pos++;
}

static int starts_or() {
    skip_spaces();
    return pos + 1 < n && s[pos] == 'o' && s[pos+1] == 'r' &&
           (pos + 2 == n || !isalnum((unsigned char)s[pos+2]));
}

static Node* parse_expr();

static Node* parse_atom() {
    skip_spaces();
    if (s[pos] == '(') {
        pos++;
        Node *x = parse_expr();
        skip_spaces();
        if (pos < n && s[pos] == ')') pos++;
        return x;
    }
    ll v = 0;
    while (pos < n && isdigit((unsigned char)s[pos])) {
        v = v * 10 + (s[pos] - '0');
        pos++;
    }
    return new_num(v);
}

static Node* parse_mul() {
    Node *first = parse_atom();
    skip_spaces();
    if (pos >= n || s[pos] != '*') return first;
    Node *x = new_node(NODE_MUL);
    add_child(x, first);
    while (1) {
        skip_spaces();
        if (pos < n && s[pos] == '*') {
            pos++;
            add_child(x, parse_atom());
        } else break;
    }
    return x;
}

static Node* parse_add() {
    Node *first = parse_mul();
    skip_spaces();
    if (pos >= n || s[pos] != '+') return first;
    Node *x = new_node(NODE_ADD);
    add_child(x, first);
    while (1) {
        skip_spaces();
        if (pos < n && s[pos] == '+') {
            pos++;
            add_child(x, parse_mul());
        } else break;
    }
    return x;
}

static Node* parse_expr() {
    Node *first = parse_add();
    skip_spaces();
    if (!starts_or()) return first;
    Node *x = new_node(NODE_OR);
    add_child(x, first);
    while (1) {
        skip_spaces();
        if (starts_or()) {
            pos += 2;
            add_child(x, parse_add());
        } else break;
    }
    return x;
}

static ll maxll(ll a, ll b) { return a > b ? a : b; }

static void solve_node(Node *u) {
    if (u->type == NODE_NUM) {
        u->plain = u->best = u->num;
        return;
    }

    for (int i = 0; i < u->cnt; i++) solve_node(u->ch[i]);

    if (u->type == NODE_OR) {
        ll v = 0;
        for (int i = 0; i < u->cnt; i++) v |= u->ch[i]->best;
        u->plain = v;
        u->best = v;
        return;
    }

    // NODE_ADD or NODE_MUL
    int m = u->cnt;
    ll *a = (ll*)malloc(m * sizeof(ll));
    for (int i = 0; i < m; i++) a[i] = u->ch[i]->plain;

    if (u->type == NODE_ADD) {
        ll sum = 0;
        for (int i = 0; i < m; i++) sum += a[i];
        u->plain = sum;

        ll *dp = (ll*)malloc((m + 1) * sizeof(ll));
        dp[m] = 0;
        for (int i = m - 1; i >= 0; i--) {
            ll cur = 0;
            ll best = 0;
            for (int j = i; j < m; j++) {
                cur += a[j];
                ll cand = cur | dp[j + 1];
                if (cand > best) best = cand;
            }
            dp[i] = best;
        }
        u->best = dp[0];
        free(dp);
    } else {
        ll prod = 1;
        for (int i = 0; i < m; i++) prod *= a[i];
        u->plain = prod;

        ll *dp = (ll*)malloc((m + 1) * sizeof(ll));
        dp[m] = 0;
        for (int i = m - 1; i >= 0; i--) {
            ll cur = 1;
            ll best = 0;
            for (int j = i; j < m; j++) {
                cur *= a[j];
                ll cand = cur | dp[j + 1];
                if (cand > best) best = cand;
            }
            dp[i] = best;
        }
        u->best = dp[0];
        free(dp);
    }
    free(a);
}

