public class Main {
    static final long NEG_INF = Long.MIN_VALUE / 2;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String s = br.readLine().trim();
        int n = s.length();

        // Parse into tokens: numbers and operators
        List<String> tokens = new ArrayList<>();
        int i = 0;
        while (i < n) {
            if (s.charAt(i) == '+' || s.charAt(i) == '*' || s.charAt(i) == '|') {
                tokens.add(String.valueOf(s.charAt(i)));
                i++;
            } else {
                // parse number
                int j = i;
                while (j < n && Character.isDigit(s.charAt(j))) j++;
                tokens.add(s.substring(i, j));
                i = j;
            }
        }

        int m = tokens.size();
        // dpMax[l][r] = max value for subexpression from token l to r inclusive
        // dpMin[l][r] = min value (needed for multiplication with negatives? but numbers are non-negative)
        // Since numbers are non-negative (digits only), min is always 0 or positive.
        // But we still track min for completeness.
        long[][] dpMax = new long[m][m];
        long[][] dpMin = new long[m][m];

        for (int l = 0; l < m; l++) {
            for (int r = 0; r < m; r++) {
                if (l == r && Character.isDigit(tokens.get(l).charAt(0))) {
                    dpMax[l][r] = Long.parseLong(tokens.get(l));
                    dpMin[l][r] = Long.parseLong(tokens.get(l));
                } else {
                    dpMax[l][r] = NEG_INF;
                    dpMin[l][r] = Long.MAX_VALUE / 2;
                }
            }
        }

        // Fill DP for increasing lengths
        for (int len = 3; len <= m; len += 2) { // length must be odd (numbers and operators alternate)
            for (int l = 0; l + len - 1 < m; l++) {
                int r = l + len - 1;
                if (tokens.get(l).matches("\\d+") && tokens.get(r).matches("\\d+")) {
                    // try splitting at each operator position
                    for (int k = l + 1; k < r; k += 2) {
                        String op = tokens.get(k);
                        long leftMax = dpMax[l][k-1];
                        long leftMin = dpMin[l][k-1];
                        long rightMax = dpMax[k+1][r];
                        long rightMin = dpMin[k+1][r];

                        if (leftMax == NEG_INF || rightMax == NEG_INF) continue;

                        long[] results = new long[4];
                        results[0] = applyOp(leftMax, op, rightMax);
                        results[1] = applyOp(leftMax, op, rightMin);
                        results[2] = applyOp(leftMin, op, rightMax);
                        results[3] = applyOp(leftMin, op, rightMin);

                        long curMax = NEG_INF;
                        long curMin = Long.MAX_VALUE / 2;
                        for (long v : results) {
                            curMax = Math.max(curMax, v);
                            curMin = Math.min(curMin, v);
                        }

                        dpMax[l][r] = Math.max(dpMax[l][r], curMax);
                        dpMin[l][r] = Math.min(dpMin[l][r], curMin);
                    }
                }
            }
        }

        long answer = dpMax[0][m-1];
        System.out.println(answer);
    }

    static long applyOp(long a, String op, long b) {
        switch (op) {
            case "+": return a + b;
            case "*": return a * b;
            case "|": return a | b;
            default: return 0;
        }
    }
}

