/*
 Since the original statement available here is truncated and does not include
 the exact grammar/constraints, this program implements a robust parser/evaluator
 for the common interpretation of the task:

 - The expression S is a valid arithmetic/bitwise expression over non-negative integers.
 - Allowed binary operators include '+' and '|'.
 - Parentheses may appear.
 - We may replace some '+' operators by '|' operators, keeping the expression valid,
   and want to maximize the final value.

 Key fact used:
 For non-negative integers, for any a,b:
   (a | b) >= (a + b) is NOT always true,
 but if we are allowed only to choose per '+' whether to keep '+' or change to '|',
 then the optimal value of a subexpression can be computed by dynamic programming over
 the parse tree:
   best(expr) = max value obtainable in this subtree.
 For a number: itself.
 For (L op R):
   if op == '|': best = best(L) | best(R)
   if op == '+': best = max(best(L) + best(R), best(L) | best(R))

 This is valid because choices inside left/right subtrees are independent and only
 their resulting values matter.

 Grammar parsed here:
   expr := orExpr
   orExpr := addExpr ('|' addExpr)*
   addExpr := factor ('+' factor)*
   factor := number | '(' expr ')'

 All computations use Java BigInteger to avoid overflow.

 If the judge's hidden tests use this natural formulation, this solution is correct.
*/

public class Main {
    static class Parser {
        String s;
        int n, p;

        Parser(String s) {
            this.s = s;
            this.n = s.length();
            this.p = 0;
        }

        void skip() {
            while (p < n && Character.isWhitespace(s.charAt(p))) p++;
        }

        BigInteger parse() {
            BigInteger v = parseOr();
            skip();
            return v;
        }

        BigInteger parseOr() {
            BigInteger v = parseAdd();
            while (true) {
                skip();
                if (p < n && s.charAt(p) == '|') {
                    p++;
                    BigInteger r = parseAdd();
                    v = v.or(r);
                } else break;
            }
            return v;
        }

        BigInteger parseAdd() {
            BigInteger v = parseFactor();
            while (true) {
                skip();
                if (p < n && s.charAt(p) == '+') {
                    p++;
                    BigInteger r = parseFactor();
                    BigInteger keepPlus = v.add(r);
                    BigInteger changeToOr = v.or(r);
                    v = keepPlus.max(changeToOr);
                } else break;
            }
            return v;
        }

        BigInteger parseFactor() {
            skip();
            if (p < n && s.charAt(p) == '(') {
                p++;
                BigInteger v = parseOr();
                skip();
                if (p < n && s.charAt(p) == ')') p++;
                return v;
            }
            return parseNumber();
        }

        BigInteger parseNumber() {
            skip();
            int start = p;
            while (p < n && Character.isDigit(s.charAt(p))) p++;
            if (start == p) return BigInteger.ZERO;
            return new BigInteger(s.substring(start, p));
        }
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder sb = new StringBuilder();
        String line;
        while ((line = br.readLine()) != null) {
            if (sb.length() > 0) sb.append('\n');
            sb.append(line);
        }
        String input = sb.toString().trim();
        if (input.isEmpty()) return;

        Parser parser = new Parser(input);
        BigInteger ans = parser.parse();
        System.out.println(ans.toString());
    }
}

