#include <bits/stdc++.h>
using namespace std;

/*
We parse expressions generated by the grammar:

<expr> ::= <term> | <expr> "xor" <term>
<term> ::= <factor> | <term> "and" <factor>
<factor> ::= <number> | "(" <expr> ")"

We may insert any number of "or" operators anywhere as long as the final string
is still a valid expression. Since "or" has lower precedence than xor/and,
inserting "or" effectively allows us to split the original expression into
several valid subexpressions and OR their values.

Thus the task becomes:
For every substring that is itself a valid expression, compute its value.
Then DP over prefixes:
dp[i] = maximum value obtainable for prefix [0..i) by partitioning it into
valid expressions and OR-ing their values.
Transition:
dp[r] = max(dp[l] | val(l,r)) for every valid expression s[l..r-1].

We parse all valid substrings with interval DP according to the grammar.

n <= manageable for O(n^3) interval DP (the original problem is designed for this).
*/

struct Val {
    bool ok = false;
    long long v = 0;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string s, t, line;
    while (getline(cin, line)) {
        if (!t.empty()) t += '\n';
        t += line;
    }
    // remove spaces/newlines/tabs
    for (char c : t) {
        if (!isspace((unsigned char)c)) s += c;
    }

    int n = (int)s.size();
    if (n == 0) {
        cout << 0 << '\n';
        return 0;
    }

    // expr[l][r], term[l][r], factor[l][r] for substring [l..r]
    vector<vector<Val>> expr(n, vector<Val>(n));
    vector<vector<Val>> term(n, vector<Val>(n));
    vector<vector<Val>> factor(n, vector<Val>(n));

    // numbers
    for (int l = 0; l < n; ++l) {
        if (isdigit((unsigned char)s[l])) {
            long long x = 0;
            for (int r = l; r < n && isdigit((unsigned char)s[r]); ++r) {
                x = x * 10 + (s[r] - '0');
                factor[l][r] = {true, x};
            }
        }
    }

    // interval DP by length
    for (int len = 1; len <= n; ++len) {
        for (int l = 0; l + len - 1 < n; ++l) {
            int r = l + len - 1;

            // factor ::= '(' expr ')'
            if (s[l] == '(' && s[r] == ')' && l + 1 <= r - 1 && expr[l + 1][r - 1].ok) {
                factor[l][r] = expr[l + 1][r - 1];
            }

            // term ::= factor | term "and" factor
            if (factor[l][r].ok) term[l][r] = factor[l][r];
            if (len >= 3) {
                for (int k = l; k <= r; ++k) {
                    if (k + 2 <= r && s.compare(k, 3, "and") == 0) {
                        int aL = l, aR = k - 1;
                        int bL = k + 3, bR = r;
                        if (aL <= aR && bL <= bR && term[aL][aR].ok && factor[bL][bR].ok) {
                            long long val = term[aL][aR].v & factor[bL][bR].v;
                            if (!term[l][r].ok) term[l][r] = {true, val};
                        }
                    }
                }
            }

            // expr ::= term | expr "xor" term
            if (term[l][r].ok) expr[l][r] = term[l][r];
            if (len >= 3) {
                for (int k = l; k <= r; ++k) {
                    if (k + 2 <= r && s.compare(k, 3, "xor") == 0) {
                        int aL = l, aR = k - 1;
                        int bL = k + 3, bR = r;
                        if (aL <= aR && bL <= bR && expr[aL][aR].ok && term[bL][bR].ok) {
                            long long val = expr[aL][aR].v ^ term[bL][bR].v;
                            if (!expr[l][r].ok) expr[l][r] = {true, val};
                        }
                    }
                }
            }
        }
    }

    // DP over partitions with OR
    const long long NEG = -1;
    vector<long long> dp(n + 1, NEG);
    dp[0] = 0;

    for (int i = 0; i < n; ++i) {
        if (dp[i] == NEG) continue;
        for (int j = i; j < n; ++j) {
            if (expr[i][j].ok) {
                dp[j + 1] = max(dp[j + 1], dp[i] | expr[i][j].v);
            }
        }
    }

    cout << dp[n] << '\n';
    return 0;
}
